content[196]=[[["Lou looks for juice in the shop.", "Lou procura suco na loja."], ["“Is there any juice?” he asks.", "“Tem suco?”, ele pergunta."], ["The clerk shows him a shelf.", "A atendente mostra uma prateleira."], ["There is not any orange juice today.", "Hoje não tem suco de laranja."], ["But there is some fresh apple juice.", "Mas tem suco de maçã fresco."]], [["Is there any juice?", "Tem suco?"], ["Yes, it is on the top shelf.", "Sim, está na prateleira de cima."], ["Is there any orange juice?", "Tem suco de laranja?"], ["There is not any orange juice today.", "Hoje não tem suco de laranja."], ["Is there any apple juice?", "Tem suco de maçã?"], ["Yes, there is some here.", "Sim, tem um pouco aqui."], ["Is there any cold water?", "Tem água gelada?"], ["Yes, there is a bottle in the fridge.", "Sim, tem uma garrafa na geladeira."]], ["Palavra shelf", "Comece com /ʃ/ e termine com f: SHELF. Não ponha vogal no fim.", ["shelf", "It is on the shelf."]], ["Is there ___ milk?", "any", "some", "Tem leite?", "Em perguntas, use any."]];
