content[200]=[[["Ava has a sister and a brother.", "Ava tem uma irmã e um irmão."], ["Her brother Noah has a small dog.", "O irmão dela, Noah, tem um cachorro pequeno."], ["They have a big family.", "Eles têm uma família grande."], ["Ava and her sisters have lunch at home.", "Ava e as irmãs almoçam em casa."], ["Her mother has a cake for them.", "A mãe dela tem um bolo para eles."]], [["Do you have a brother?", "Você tem um irmão?"], ["Yes, I have one brother.", "Sim, tenho um irmão."], ["Do you have sisters too?", "Você também tem irmãs?"], ["I have two sisters.", "Tenho duas irmãs."], ["Does your brother have a job?", "Seu irmão tem um emprego?"], ["Yes, he has a job in a bank.", "Sim, ele tem um emprego em um banco."], ["Do you have a big family?", "Você tem uma família grande?"], ["Yes, we have six people at home.", "Sim, somos seis pessoas em casa."]], ["/h/ em have e has", "Sopre o ar de leve pela garganta, sem raspar: é quase só um suspiro antes da vogal.", ["has", "Ava has a sister."]], ["Ava ___ two sisters.", "has", "have", "Ava tem duas irmãs.", "Com nomes no singular (como he e she), o verbo é has."]];
