content[201]=[[["Ravi’s mother is at the door.", "A mãe do Ravi está na porta."], ["Ravi’s uncle has a new car.", "O tio do Ravi tem um carro novo."], ["The color of the car is red.", "A cor do carro é vermelha."], ["Ravi’s mother likes the car.", "A mãe do Ravi gosta do carro."], ["They go to Ravi’s uncle’s house.", "Eles vão à casa do tio do Ravi."]], [["Who is that woman?", "Quem é aquela mulher?"], ["She is Ben’s mother.", "Ela é a mãe do Ben."], ["Is the man her brother?", "O homem é irmão dela?"], ["No, he is Ben’s uncle.", "Não, ele é o tio do Ben."], ["Where is the house of your uncle?", "Onde fica a casa do seu tio?"], ["It is near the park.", "Fica perto do parque."], ["Is the house of your uncle big?", "A casa do seu tio é grande?"], ["Yes, it has five rooms.", "Sim, tem cinco cômodos."]], ["O som /z/ final em ’s", "Em Ravi’s e Ben’s, o ’s soa como um z zumbido, com a voz ligada.", ["Ben’s", "Ben’s mother is here."]], ["This is ___ bag.", "Lia’s", "Lias", "Esta é a bolsa da Lia.", "Para mostrar o dono, junte ’s ao nome."]];
