content[202]=[[["Noah shows a photo of his grandmother.", "Noah mostra uma foto da avó dele."], ["Her name is Rosa.", "O nome dela é Rosa."], ["His grandfather is next to her.", "O avô dele está ao lado dela."], ["Their house is by the lake.", "A casa deles fica perto do lago."], ["Noah says our family is big.", "Noah diz que a nossa família é grande."]], [["Is this your grandmother?", "Esta é a sua avó?"], ["Yes, her name is Rosa.", "Sim, o nome dela é Rosa."], ["Is that your grandfather?", "Aquele é o seu avô?"], ["Yes, his name is Paulo.", "Sim, o nome dele é Paulo."], ["Where is their house?", "Onde fica a casa deles?"], ["Their house is near here.", "A casa deles fica perto daqui."], ["Is this photo for our wall?", "Esta foto é para a nossa parede?"], ["Yes, our wall is empty.", "Sim, a nossa parede está vazia."]], ["/ð/ em their", "Ponha a ponta da língua entre os dentes e vibre a voz: their não começa com d.", ["their", "Their house is big."]], ["Ben has a dog. ___ name is Rex.", "His", "He", "Ben tem um cachorro. O nome dele é Rex.", "Antes de um substantivo, use his, não he."]];
