content[204]=[[["Ben looks for his cat.", "Ben procura o gato dele."], ["It is not on the sofa.", "Ele não está no sofá."], ["It is not behind the door.", "Ele não está atrás da porta."], ["The cat is under the bed.", "O gato está embaixo da cama."], ["Ben puts a bowl on the floor.", "Ben põe uma tigela no chão."]], [["Where is my phone?", "Onde está meu telefone?"], ["It is on the sofa.", "Está no sofá."], ["Where are the keys?", "Onde estão as chaves?"], ["They are in the bag.", "Estão na bolsa."], ["Is the lamp behind the sofa?", "O abajur está atrás do sofá?"], ["No, it is between the bed and the wall.", "Não, está entre a cama e a parede."], ["So the cat is under the table?", "Então o gato está embaixo da mesa?"], ["Yes, it is under the table.", "Sim, está embaixo da mesa."]], ["/ʌ/ em under", "Abra a boca de leve e solte um a curto e relaxado, sem fechar em u.", ["under", "The cat is under the bed."]], ["The cat is ___ the bed.", "under", "down", "O gato está embaixo da cama.", "Para dizer embaixo de algo, use under."]];
