content[208]=[[["Peg has a new neighbor.", "Peg tem uma vizinha nova."], ["Peg asks who lives next door.", "Peg pergunta quem mora na casa ao lado."], ["The neighbor is June.", "A vizinha é a June."], ["June lives with her aunt.", "June mora com a tia dela."], ["Peg says hello to June and her aunt.", "Peg cumprimenta June e a tia dela."]], [["Who lives in this house?", "Quem mora nesta casa?"], ["My aunt lives here with me.", "Minha tia mora aqui comigo."], ["Where does your aunt work?", "Onde a sua tia trabalha?"], ["She works at a school.", "Ela trabalha em uma escola."], ["Who lives next door?", "Quem mora ao lado?"], ["A new neighbor lives there.", "Um vizinho novo mora lá."], ["So your aunt lives with you?", "Então a sua tia mora com você?"], ["Yes, she lives here with my dog.", "Sim, ela mora aqui com o meu cachorro."]], ["S final em lives", "Em lives, o s final soa como z, com a voz ligada: livz.", ["lives", "She lives here."]], ["___ next door?", "Who lives", "Who does live", "Quem mora ao lado?", "Com who no lugar do sujeito, use o verbo direto, sem does."]];
