content[211]=[[["Noah lives in a small town.", "Noah mora em uma cidade pequena."], ["The weather is cold in winter.", "O clima é frio no inverno."], ["It is hot in summer.", "É quente no verão."], ["Noah likes the weather in spring.", "Noah gosta do clima na primavera."], ["Noah likes summer, but his sister likes winter.", "Noah gosta do verão, mas a irmã dele gosta do inverno."]], [["What is the weather like in winter?", "Como é o clima no inverno?"], ["It is very cold.", "É muito frio."], ["What is the weather like in summer?", "Como é o clima no verão?"], ["It is hot and sunny.", "É quente e ensolarado."], ["What is the weather like today?", "Como está o tempo hoje?"], ["It is rainy and cool.", "Está chuvoso e fresco."], ["So summer is hot there?", "Então o verão é quente aí?"], ["Yes, and winter is very cold.", "Sim, e o inverno é muito frio."]], ["/w/ em winter e weather", "Arredonde os lábios como em u e abra rápido: winter e weather começam igual.", ["weather", "The weather is good."]], ["What is the weather ___ in winter?", "like", "as", "Como é o clima no inverno?", "Para perguntar como algo é, use What is… like?"]];
