content[214]=[[["Tina wants a new bag.", "Tina quer uma bolsa nova."], ["The store has a black bag and a blue bag.", "A loja tem uma bolsa preta e uma azul."], ["Tina likes the color green.", "Tina gosta da cor verde."], ["A green bag is in the window.", "Uma bolsa verde está na vitrine."], ["She pays twenty dollars and says thank you.", "Ela paga vinte dólares e agradece."]], [["What color is your bag?", "De que cor é a sua bolsa?"], ["It is a green bag.", "É uma bolsa verde."], ["What color is the jacket?", "De que cor é a jaqueta?"], ["It is a dark blue jacket.", "É uma jaqueta azul-escura."], ["Do you like the pink hat?", "Você gosta do chapéu rosa?"], ["No, I like the white hat.", "Não, gosto do chapéu branco."], ["So you want a green bag?", "Então você quer uma bolsa verde?"], ["Yes, I love the color.", "Sim, adoro a cor."]], ["/r/ em green", "Puxe a língua para trás sem encostar no céu da boca: green não tem o r forte do português.", ["green", "I like the green bag."]], ["I have a ___.", "green bag", "bag green", "Eu tenho uma bolsa verde.", "Em inglês a cor vem antes do substantivo."]];
