content[217]=[[["Tina shows two jeans to Lou.", "Tina mostra duas calças para o Lou."], ["This one has a big pocket.", "Esta tem um bolso grande."], ["That one has two small pockets.", "Aquela tem dois bolsos pequenos."], ["Which one does Lou like?", "De qual o Lou gosta?"], ["He likes this one, so Tina buys it.", "Ele gosta desta, então a Tina compra."]], [["Which one do you like?", "De qual você gosta?"], ["I like this one with the big pocket.", "Gosto desta com o bolso grande."], ["Which one is yours?", "Qual é a sua?"], ["That one over there is mine.", "Aquela ali é a minha."], ["Which boots do you want?", "Quais botas você quer?"], ["I want those brown boots.", "Quero aquelas botas marrons."], ["So this one is for Tina?", "Então esta é para a Tina?"], ["Yes, and that one is for Lou.", "Sim, e aquela é para o Lou."]], ["/θ/ e /ð/ em this e that", "Em this e that, a ponta da língua toca os dentes e a voz vibra: não diga dis nem dat.", ["this", "This one is mine."]], ["___ one do you want?", "Which", "What", "Qual você quer?", "Para escolher entre opções, use which."]];
