plans[218]={"title": "Antes de sair de casa", "file": "photo-dusk-1.webp", "grammar": "Imperativo com conselhos de clima", "goal": "Dê conselhos com o verbo base no início: Take an umbrella. Wear a coat. Do not forget…", "words": [["umbrella", "guarda-chuva"], ["coat", "casaco"], ["take", "levar"], ["close", "fechar"]]};
content[218]=[[["Peg looks out the window.", "Peg olha pela janela."], ["It is rainy and cold today.", "Hoje está chuvoso e frio."], ["Ben says, Take an umbrella.", "Ben diz: leve um guarda-chuva."], ["He also says, Wear a coat.", "Ele também diz: vista um casaco."], ["Peg takes both and goes out.", "Peg leva os dois e sai."]], [["What is the weather like?", "Como está o tempo?"], ["It is cold. Wear a coat.", "Está frio. Vista um casaco."], ["Is it rainy now?", "Está chovendo agora?"], ["Yes, take an umbrella.", "Sim, leve um guarda-chuva."], ["Should I wear a hat?", "Devo usar chapéu?"], ["Yes, wear a hat and a scarf.", "Sim, use chapéu e cachecol."], ["So I take my coat and umbrella?", "Então levo o casaco e o guarda-chuva?"], ["Yes, and close the door.", "Sim, e feche a porta."]], ["Acento em umbrella", "Na palavra umbrella, a segunda sílaba é a forte: um-BREL-la.", ["umbrella", "Take an umbrella."]], ["___ an umbrella today.", "Take", "You take", "Leve um guarda-chuva hoje.", "No conselho, comece com o verbo base, sem you."]];
