content[219]=[[["Ava looks at the sky.", "Ava olha para o céu."], ["There is a big cloud over the park.", "Há uma nuvem grande sobre o parque."], ["It is windy and cold.", "Está ventando e frio."], ["She is wearing a thin jacket.", "Ela está com uma jaqueta fina."], ["Ava takes a coat and goes out.", "Ava pega um casaco e sai."]], [["Is it windy today?", "Está ventando hoje?"], ["Yes, it is very windy.", "Sim, está ventando muito."], ["Is there a cloud in the sky?", "Tem nuvem no céu?"], ["Yes, there is a big gray cloud.", "Sim, tem uma nuvem cinza grande."], ["What are you wearing?", "O que você está vestindo?"], ["I am wearing a coat and a hat.", "Estou de casaco e chapéu."], ["So we need an umbrella?", "Então precisamos de um guarda-chuva?"], ["Yes, take it and let us go.", "Sim, leve e vamos."]], ["/k/ em cloud", "Feche a garganta com o fundo da língua e solte com um sopro: cloud começa com k forte.", ["cloud", "There is a cloud."]], ["It is ___ today.", "windy", "wind", "Hoje está ventando.", "Depois de it is, use o adjetivo windy, não o substantivo wind."]];
