content[222]=[[["Ben can drive, but he cannot swim.", "Ben sabe dirigir, mas não sabe nadar."], ["He wants to swim this summer.", "Ele quer nadar neste verão."], ["Ava can swim very well.", "Ava nada muito bem."], ["She helps him at the pool.", "Ela o ajuda na piscina."], ["Ben is slow, but he is happy.", "Ben é lento, mas está feliz."]], [["Can you swim, Ben?", "Você sabe nadar, Ben?"], ["No, I cannot swim.", "Não, eu não sei nadar."], ["Can you drive a car?", "Você sabe dirigir?"], ["Yes, I can drive very well.", "Sim, dirijo muito bem."], ["Can Ava swim?", "A Ava sabe nadar?"], ["Yes, she can swim fast.", "Sim, ela nada rápido."], ["Can she help me on Sunday?", "Ela pode me ajudar no domingo?"], ["Yes, she can come at ten.", "Sim, ela pode vir às dez."]], ["Can e cannot", "Em can, a vogal é fraca (/kən/); em cannot, o acento cai na segunda sílaba: can-NOT.", ["cannot", "I cannot swim."]], ["I ___ swim.", "cannot", "no can", "Eu não sei nadar.", "A negação de can é cannot, nunca no can."]];
