content[223]=[[["On Saturday, Ravi has a party at home.", "No sábado, Ravi faz uma festa em casa."], ["He enjoys cooking with his friends.", "Ele curte cozinhar com os amigos."], ["Lia loves painting, so she brings paper.", "Lia adora pintar, então leva papel."], ["Ben likes dancing in the kitchen.", "Ben gosta de dançar na cozinha."], ["Everyone is happy, and the food is great.", "Todos estão felizes, e a comida está ótima."]], [["What do you enjoy doing on Saturday?", "O que você curte fazer no sábado?"], ["I enjoy cooking for my friends.", "Curto cozinhar para meus amigos."], ["Do you like dancing?", "Você gosta de dançar?"], ["Yes, I love dancing.", "Sim, eu adoro dançar."], ["Do you like singing too?", "Você também gosta de cantar?"], ["No, I like listening to music.", "Não, gosto de ouvir música."], ["Do you enjoy painting, Lia?", "Você curte pintar, Lia?"], ["Yes, I love painting with Ravi.", "Sim, adoro pintar com o Ravi."]], ["Terminação -ing", "Em cooking e painting, o ing é curto: língua alta, sem pronunciar um g forte no fim.", ["cooking", "I enjoy cooking."]], ["I enjoy ___ dinner.", "cooking", "to cook", "Eu curto cozinhar o jantar.", "Depois de enjoy, o verbo vai com -ing."]];
