content[225]=[[["Ava has homework after school.", "Ava tem lição de casa depois da aula."], ["She has to read two pages first.", "Ela tem que ler duas páginas primeiro."], ["Her brother Nico has to wash the dishes.", "O irmão dela, Nico, tem que lavar a louça."], ["Mom says, \"You both have to work first.\"", "A mãe diz: \"Vocês dois têm que trabalhar primeiro.\""], ["Then they can play outside.", "Depois eles podem brincar lá fora."]], [["Do you have to work today?", "Você tem que trabalhar hoje?"], ["Yes, I have to work at five.", "Sim, tenho que trabalhar às cinco."], ["What does Ava have to do?", "O que a Ava tem que fazer?"], ["She has to do her homework.", "Ela tem que fazer a lição de casa."], ["Do you have to wash the dishes?", "Você tem que lavar a louça?"], ["Yes, I have to wash them now.", "Sim, tenho que lavá-la agora."], ["Do you have to clean your room?", "Você tem que limpar seu quarto?"], ["No, I do not have to clean it.", "Não, eu não preciso limpá-lo."]], ["Has to", "Em has to, o s soa como /s/ e o to fica fraco: HAS-tə.", ["homework", "I have homework."]], ["Ava ___ do her homework.", "has to", "have to", "Ava tem que fazer a lição de casa.", "Com he ou she, use has to."]];
