content[226]=[[["The market starts at seven in the morning.", "O mercado abre às sete da manhã."], ["It finishes at four in the afternoon.", "Ele termina às quatro da tarde."], ["Ravi works from eight to two there.", "Ravi trabalha lá das oito às duas."], ["Tina works from two to four.", "Tina trabalha das duas às quatro."], ["Then they close the market and go home.", "Depois eles fecham o mercado e vão para casa."]], [["What time does the market start?", "A que horas o mercado começa?"], ["It starts at seven.", "Começa às sete."], ["When does it finish?", "Quando ele termina?"], ["It finishes at four.", "Termina às quatro."], ["Do you work all day?", "Você trabalha o dia todo?"], ["No, I work from eight to two.", "Não, trabalho das oito às duas."], ["Who works after that?", "Quem trabalha depois disso?"], ["Tina does. She works from two to four.", "A Tina. Ela trabalha das duas às quatro."]], ["Final de finish", "Em finish, o final -sh é um chiado longo, com os lábios um pouco arredondados.", ["finish", "I finish at four."]], ["The market starts ___ seven.", "at", "in", "O mercado abre às sete.", "Use at com a hora exata."]];
