content[233]=[[["Nico walks out of his house at nine.", "Nico sai de casa às nove."], ["He walks along the river for ten minutes.", "Ele anda ao longo do rio por dez minutos."], ["Then he goes across the bridge.", "Depois ele atravessa a ponte."], ["After that, he walks through the park.", "Depois disso, ele passa pelo parque."], ["Finally, he goes into a small shop.", "Por fim, ele entra em uma lojinha."]], [["Where do you walk in the morning?", "Onde você caminha de manhã?"], ["I walk along the river.", "Caminho ao longo do rio."], ["Do you go across the bridge?", "Você atravessa a ponte?"], ["Yes, then I go through the park.", "Sim, depois passo pelo parque."], ["Where do you stop?", "Onde você para?"], ["I go into the bakery on the corner.", "Entro na padaria da esquina."], ["What time do you come out of it?", "A que horas você sai de lá?"], ["I come out of it at ten.", "Saio de lá às dez."]], ["Ligação em out of", "Em out of, ligue as palavras: ou-tov. O of fica fraco, quase só /əv/.", ["through", "I walk through the park."]], ["He walks ___ the bridge.", "across", "in", "Ele atravessa a ponte.", "Across indica ir de um lado ao outro."]];
