content[234]=[[["Ben goes to the ticket window.", "Ben vai ao guichê."], ["He says, \"One adult and two children, please.\"", "Ele diz: \"Um adulto e duas crianças, por favor.\""], ["The woman says an adult ticket is four dollars.", "A mulher diz que a passagem de adulto custa quatro dólares."], ["Children pay only one dollar each.", "Crianças pagam só um dólar cada."], ["Ben pays and gets three tickets.", "Ben paga e recebe três passagens."]], [["Hello. How much is a ticket to the lake?", "Olá. Quanto custa a passagem para o lago?"], ["An adult ticket is four dollars.", "A de adulto custa quatro dólares."], ["And how much is a child ticket?", "E quanto custa a de criança?"], ["It is one dollar.", "Custa um dólar."], ["One adult and two children, please.", "Um adulto e duas crianças, por favor."], ["That is six dollars.", "São seis dólares."], ["Here is ten dollars. Is that OK?", "Aqui estão dez dólares. Pode ser?"], ["Yes, here are four dollars back.", "Sim, aqui estão quatro dólares de troco."]], ["Som do CH em children", "Comece com t e solte o ch como em chuva; a primeira sílaba é fraca e curta.", ["children", "Two children, please."]], ["One adult and two ___, please.", "children", "childs", "Um adulto e duas crianças, por favor.", "O plural de child é children."]];
