content[238]=[[["Noah is at a busy train station.", "Noah está em uma estação de trem movimentada."], ["He asks, \"Which train goes to the beach?\"", "Ele pergunta: \"Qual trem vai à praia?\""], ["A worker says, \"Train five goes there.\"", "Um funcionário diz: \"O trem cinco vai para lá.\""], ["It leaves from platform two at noon.", "Ele sai da plataforma dois ao meio-dia."], ["Noah runs and gets on the train.", "Noah corre e entra no trem."]], [["Which train goes to the city center?", "Qual trem vai ao centro?"], ["The blue train goes there.", "O trem azul vai para lá."], ["Where does it leave from?", "De onde ele sai?"], ["It leaves from platform four.", "Sai da plataforma quatro."], ["Does it leave soon?", "Ele sai logo?"], ["Yes, it leaves in five minutes.", "Sim, sai em cinco minutos."], ["Which train goes to the lake?", "Qual trem vai ao lago?"], ["The green one goes to the lake.", "O verde vai ao lago."]], ["Ritmo em platform", "Em platform, a força cai na primeira sílaba: PLAT-form, com a vogal aberta.", ["platform", "Go to platform two."]], ["Which train ___ to the beach?", "goes", "go", "Qual trem vai à praia?", "Which train é singular, então o verbo leva -es."]];
