content[239]=[[["Lia takes a city tour today.", "Lia faz um passeio pela cidade hoje."], ["The guide is a friendly woman named Peg.", "A guia é uma mulher simpática chamada Peg."], ["The tour bus is bigger than a normal bus.", "O ônibus do passeio é maior que um ônibus comum."], ["Peg says, \"Look at the museum on the right.\"", "Peg diz: \"Olhem o museu à direita.\""], ["It is opposite the old bridge.", "Fica em frente à ponte velha."]], [["Is the tour long?", "O passeio é longo?"], ["It takes two hours.", "Leva duas horas."], ["How far is the museum?", "Quão longe fica o museu?"], ["It is only two miles from here.", "Fica a só duas milhas daqui."], ["Which bus goes to the bridge?", "Qual ônibus vai à ponte?"], ["The blue bus goes there.", "O ônibus azul vai para lá."], ["Is the guide more interesting than the map?", "A guia é mais interessante que o mapa?"], ["Yes, she is much more interesting.", "Sim, ela é bem mais interessante."]], ["Som /ɪ/ em city", "Em city, o i é curto e o t soa quase como um d rápido: SID-i.", ["city", "The city is big."]], ["The bus is ___ than the train.", "slower", "more slow", "O ônibus é mais lento que o trem.", "Adjetivo curto recebe -er antes de than."]];
