content[263]=[[["Ava likes to cook with her brother.", "Ava gosta de cozinhar com o irmão."], ["Yesterday she cooked rice and fish.", "Ontem ela cozinhou arroz e peixe."], ["Noah cleaned the kitchen after dinner.", "Noah limpou a cozinha depois do jantar."], ["Then they watched a movie.", "Depois eles assistiram a um filme."], ["Noah wanted to clean the table too.", "Noah também queria limpar a mesa."]], [["Who cooked dinner last night?", "Quem cozinhou o jantar ontem à noite?"], ["Ava cooked rice and fish.", "A Ava cozinhou arroz e peixe."], ["Who cleaned the kitchen?", "Quem limpou a cozinha?"], ["I cleaned it after dinner.", "Eu limpei depois do jantar."], ["Do you like to cook?", "Você gosta de cozinhar?"], ["Yes, I cooked soup last week.", "Sim, eu cozinhei sopa semana passada."], ["Who watched the movie with you?", "Quem assistiu ao filme com você?"], ["Ava watched it with me.", "A Ava assistiu comigo."]], ["Final -ed como /t/ e /d/", "Depois de som surdo (cooked) o -ed soa /t/; depois de som sonoro (cleaned) soa /d/.", ["cooked", "She cooked rice."]], ["Yesterday Ava ___ rice.", "cooked", "cook", "Ontem a Ava cozinhou arroz.", "Ação terminada no passado leva verbo com -ed."]];
