content[269]=[[["Last weekend was warm and sunny.", "O fim de semana passado foi quente e ensolarado."], ["Peg had a picnic with Nico.", "A Peg fez um piquenique com o Nico."], ["They saw ducks at the lake.", "Eles viram patos no lago."], ["Nico did not bring a spoon.", "O Nico não trouxe uma colher."], ["Peg laughed and shared hers.", "A Peg riu e dividiu a dela."]], [["How was your weekend?", "Como foi o seu fim de semana?"], ["It was great. We had a picnic.", "Foi ótimo. Fizemos um piquenique."], ["Where did you go?", "Aonde vocês foram?"], ["We went to the lake.", "Fomos ao lago."], ["Did you see any ducks?", "Vocês viram patos?"], ["Yes, we saw five ducks.", "Vimos, vimos cinco patos."], ["Did Nico bring food?", "O Nico trouxe comida?"], ["No, he did not. I cooked.", "Não. Eu cozinhei."]], ["Acento em weekend", "A força fica na primeira sílaba: WEEK-end.", ["weekend", "It was a good weekend."]], ["Peg ___ a picnic last weekend.", "had", "have", "A Peg fez um piquenique no fim de semana passado.", "Com last weekend o verbo vai para o passado: had."]];
