content[271]=[[["Tina is standing at the hotel door.", "A Tina está parada na porta do hotel."], ["A taxi is waiting outside.", "Um táxi está esperando do lado de fora."], ["The driver asks where she is going.", "O motorista pergunta aonde ela vai."], ["She is going to the train station.", "Ela vai para a estação de trem."], ["Lou is going with her.", "O Lou vai com ela."]], [["Where are you going today?", "Aonde você vai hoje?"], ["I am going to the station.", "Vou para a estação."], ["Who is going with you?", "Quem vai com você?"], ["Lou is going with me.", "O Lou vai comigo."], ["What are you going to do there?", "O que você vai fazer lá?"], ["We are going to buy tickets.", "Vamos comprar passagens."], ["Is the taxi going to wait?", "O táxi vai esperar?"], ["Yes, it is going to wait.", "Sim, vai esperar."]], ["/w/ em where", "Lábios arredondados para o w, depois “ér”: where, não “uére” com v.", ["where", "Where are you going?"]], ["Where ___ you going?", "are", "is", "Aonde você vai?", "Com you usamos are."]];
