content[272]=[[["June stands at the hotel desk.", "A June está no balcão do hotel."], ["She would like a room for two nights.", "Ela gostaria de um quarto para duas noites."], ["The room is on the third floor.", "O quarto fica no terceiro andar."], ["It has a big bed and a window.", "Tem uma cama grande e uma janela."], ["June likes it and says thank you.", "A June gosta e agradece."]], [["Hello. How can I help you?", "Olá. Como posso ajudar?"], ["I would like a room, please.", "Eu gostaria de um quarto, por favor."], ["For how many nights?", "Para quantas noites?"], ["I would like two nights.", "Eu gostaria de duas noites."], ["Would you like one bed or two?", "Você gostaria de uma cama ou duas?"], ["I would like one big bed.", "Eu gostaria de uma cama grande."], ["Is the room quiet?", "O quarto é silencioso?"], ["Yes, it is. It is on the third floor.", "Sim, é. Fica no terceiro andar."]], ["O l mudo em would", "Em would o l não soa: diga “wud”.", ["would", "I would like a room."]], ["I ___ like a room, please.", "would", "will", "Eu gostaria de um quarto, por favor.", "O pedido educado usa would like."]];
