content[273]=[[["Ben checks in at a small hotel.", "O Ben faz check-in em um hotel pequeno."], ["He is going to stay for five nights.", "Ele vai ficar cinco noites."], ["Lia stays for only two nights.", "A Lia fica só duas noites."], ["She has to leave on Friday.", "Ela tem que partir na sexta-feira."], ["Ben loves the city and the beach.", "O Ben adora a cidade e a praia."]], [["How long are you staying?", "Quanto tempo você vai ficar?"], ["I am staying for five nights.", "Vou ficar cinco noites."], ["Is your friend staying too?", "Seu amigo também vai ficar?"], ["Yes, she is staying for two nights.", "Sim, ela vai ficar duas noites."], ["When does she leave?", "Quando ela vai embora?"], ["She leaves on Friday morning.", "Ela vai embora na sexta de manhã."], ["So you are staying for five nights?", "Então você vai ficar cinco noites?"], ["Yes, five nights. That is correct.", "Sim, cinco noites. Está correto."]], ["O som /ŋ/ em long", "O ng é um som só, no fundo da garganta: long, não “longue”.", ["long", "How long is it?"]], ["I am staying ___ five nights.", "for", "since", "Vou ficar cinco noites.", "Para a duração usamos for + período."]];
