content[275]=[[["Peg arrives at the hotel at noon.", "A Peg chega ao hotel ao meio-dia."], ["Check in is at three.", "O check-in é às três."], ["She can leave her bag at the desk.", "Ela pode deixar a mala no balcão."], ["Check out is at eleven the next day.", "O check-out é às onze do dia seguinte."], ["She wants to check out early.", "Ela quer fazer check-out cedo."]], [["What time is check in?", "A que horas é o check-in?"], ["Check in is at three.", "O check-in é às três."], ["And what time is check out?", "E a que horas é o check-out?"], ["Check out is at eleven.", "O check-out é às onze."], ["Can I leave my bag here?", "Posso deixar minha mala aqui?"], ["Yes, you can leave it here.", "Sim, pode deixar aqui."], ["So check out is at eleven?", "Então o check-out é às onze?"], ["Yes, eleven sharp.", "Sim, onze em ponto."]], ["O som /tʃ/ em check", "Junte t e ch: “tch”, com a língua atrás dos dentes de cima.", ["check", "Check in is at three."]], ["Check in is ___ three.", "at", "in", "O check-in é às três.", "Para horas exatas usamos at."]];
