plans[279]={"title": "A viagem curta de Lia", "file": "photo-luggage-1.webp", "grammar": "Revisão: uma viagem curta (mini-história)", "goal": "Junte going to, would like, check in, for + período e pedidos para planejar uma viagem.", "words": [["suitcase", "mala"], ["plan", "plano"], ["rain", "chover"], ["fun", "diversão"]]};
content[279]=[[["Lia is going to take a small suitcase.", "A Lia vai levar uma mala pequena."], ["Lou is going to bring an umbrella.", "O Lou vai levar um guarda-chuva."], ["It is going to rain on Friday.", "Vai chover na sexta-feira."], ["They are going to stay for two nights.", "Eles vão ficar duas noites."], ["Lia says they are going to have fun.", "A Lia diz que eles vão se divertir."]], [["Are you going to take a suitcase?", "Você vai levar uma mala?"], ["Yes, a small one.", "Sim, uma pequena."], ["Is it going to rain there?", "Vai chover lá?"], ["Yes, so I am going to bring an umbrella.", "Vai, então vou levar um guarda-chuva."], ["How long are you going to stay?", "Quanto tempo vocês vão ficar?"], ["We are going to stay for two nights.", "Vamos ficar duas noites."], ["Are you going to leave tomorrow?", "Vocês vão partir amanhã?"], ["Yes, at nine. Our flight is at noon.", "Sim, às nove. O voo é ao meio-dia."]], ["Acento em suitcase", "A força fica na primeira sílaba: SUIT-case.", ["suitcase", "A small suitcase."]], ["It ___ going to rain on Friday.", "is", "are", "Vai chover na sexta-feira.", "Com it usamos is."]];
patterns[279]=new RegExp("\\b(?:am|is|are) going to\\b","i");
themes[279]="map";
photos[279]=["photo-luggage-1.webp", "photo-train-2.webp"];
stories[279]=["Lia vai viajar", "Lia is going to take a short trip.~A Lia vai fazer uma viagem curta.|She would like a room for two nights.~Ela gostaria de um quarto para duas noites.|Her flight is at nine tomorrow morning.~O voo dela é às nove amanhã de manhã.|At the airport, she shows her passport.~No aeroporto, ela mostra o passaporte.|She goes to gate five and waits.~Ela vai ao portão cinco e espera.|The hotel is going to have free breakfast.~O hotel vai ter café da manhã grátis.|Check in is at three, but Lia is early.~O check-in é às três, mas a Lia chegou cedo.|She asks, “Can you keep my bag, please?”~Ela pergunta: “Pode guardar minha mala, por favor?”|The woman says yes and gives her tea.~A mulher diz sim e lhe dá chá.|Lia smiles because the room is quiet.~A Lia sorri porque o quarto é silencioso."];
extras[279]={"plan": ["We have a plan for the trip.", "Nós temos um plano para a viagem."]};
plans[280]={"title": "Bolo na festa da Peg", "file": "photo-bakery-1.webp", "grammar": "Would you like some…? para oferecer", "goal": "Use Would you like some + comida ou bebida para oferecer algo com educação.", "words": [["cake", "bolo"], ["pizza", "pizza"], ["tea", "chá"], ["plate", "prato"]]};
content[280]=[[["Peg has a party at her house.", "A Peg faz uma festa na casa dela."], ["She puts a big cake on the table.", "Ela põe um bolo grande na mesa."], ["Ravi comes in with a big pizza.", "Ravi chega com uma pizza grande."], ["Peg asks, “Would you like some tea?”", "A Peg pergunta: “Você quer um pouco de chá?”"], ["Ravi says yes and takes a plate.", "O Ravi diz que sim e pega um prato."]], [["Would you like some cake?", "Você quer um pouco de bolo?"], ["Yes, please. It looks good.", "Sim, por favor. Parece bom."], ["Would you like some pizza too?", "Você quer um pouco de pizza também?"], ["No, thank you. I am full.", "Não, obrigado. Estou satisfeito."], ["Would you like some tea then?", "Então quer um pouco de chá?"], ["Yes, I would. Green tea, please.", "Sim, quero. Chá verde, por favor."], ["Would you like some more cake?", "Quer mais um pouco de bolo?"], ["Yes, one small piece, please.", "Sim, um pedaço pequeno, por favor."]], ["O som /k/ em cake e pizza", "Solte o ar com um pequeno estouro no fundo da garganta, sem vogal depois, como o c de casa.", ["cake", "The cake is on the plate."]], ["Would you like ___ cake?", "some", "a", "Você quer um pouco de bolo?", "Para oferecer comida ou bebida, use Would you like some."]];
