plans[281]={"title": "Obrigado, de nada", "file": "photo-counter-1.webp", "grammar": "Thank you for…, You are welcome e Excuse me para cortesia", "goal": "Use Thank you for, You are welcome e Excuse me para ser educado em situações simples.", "words": [["excuse me", "com licença"], ["welcome", "de nada"], ["thank", "agradecer"], ["help", "ajuda"]]};
content[281]=[[["Noah stands at the door of the shop.", "O Noah está parado na porta da loja."], ["He says, “Excuse me, can I come in?”", "Ele diz: “Com licença, posso entrar?”"], ["Tina smiles and opens the door for him.", "A Tina sorri e abre a porta para ele."], ["Noah says, “Thank you for your help.”", "O Noah diz: “Obrigado pela sua ajuda.”"], ["Tina says, “You are welcome. Come in!”", "A Tina diz: “De nada. Entre!”"]], [["Excuse me, where is the bank?", "Com licença, onde fica o banco?"], ["It is next to the park.", "Fica ao lado do parque."], ["Thank you for your help.", "Obrigado pela sua ajuda."], ["You are welcome. Is it far?", "De nada. É longe?"], ["Excuse me, is this seat free?", "Com licença, este lugar está livre?"], ["Yes, it is. Please sit down.", "Está, sim. Sente-se, por favor."], ["Thank you for the water.", "Obrigado pela água."], ["You are welcome. Have a nice day.", "De nada. Tenha um bom dia."]], ["O som /θ/ em thank", "Ponha a ponta da língua entre os dentes e sopre. Não troque por t ou f.", ["thank", "Thank you for the water."]], ["Thank you ___ your help.", "for", "to", "Obrigado pela sua ajuda.", "Em inglês, agradecemos por algo com for."]];
