content[282]=[[["Lou sees Ava at the entrance.", "O Lou vê a Ava na entrada."], ["He waves at her, and she waves at him.", "Ele acena para ela, e ela acena para ele."], ["Ava gives him a hug.", "A Ava dá um abraço nele."], ["Ben and June are late, so they call us.", "O Ben e a June estão atrasados, então ligam para nós."], ["We wait for them at the door.", "Nós esperamos por eles na porta."]], [["Do you see Ava over there?", "Você vê a Ava ali?"], ["Yes, I see her. She waves at me.", "Vejo, sim. Ela acena para mim."], ["Where are Ben and June?", "Onde estão o Ben e a June?"], ["They are late. I will call them.", "Eles estão atrasados. Vou ligar para eles."], ["Do you want to wait for them?", "Você quer esperar por eles?"], ["Yes, please wait with us.", "Sim, espere conosco, por favor."], ["Is Lou here too?", "O Lou está aqui também?"], ["Yes, I see him. Give him a hug.", "Está. Eu o vejo. Dê um abraço nele."]], ["O som /h/ em him e her", "O h é só um sopro leve, como um suspiro. Não pronuncie como o r do português.", ["her", "I call her at five."]], ["I see Ava. I wave at ___.", "her", "she", "Eu vejo a Ava. Eu aceno para ela.", "Depois do verbo ou de at, use o pronome objeto her."]];
