content[289]=[[["Ben plans a party for Peg.", "O Ben planeja uma festa para a Peg."], ["Her birthday is on April twentieth.", "O aniversário dela é no dia vinte de abril."], ["He asks every guest to come at five.", "Ele pede a cada convidado que venha às cinco."], ["Ava brings a balloon, and Ravi brings a cake.", "A Ava traz um balão, e o Ravi traz um bolo."], ["Peg comes in, and all the guests clap.", "A Peg entra, e todos os convidados batem palmas."]], [["Can you come to the party?", "Você pode vir à festa?"], ["Yes, I can. When is it?", "Posso, sim. Quando é?"], ["It is on April twentieth.", "É no dia vinte de abril."], ["Who is the party for?", "Para quem é a festa?"], ["It is for Peg. Please give her this balloon.", "É para a Peg. Por favor, dê este balão a ela."], ["Sure. Would you like some cake?", "Claro. Você quer um pouco de bolo?"], ["Yes, thank you. Is it a surprise?", "Quero, obrigado. É uma surpresa?"], ["Yes, so please do not tell her.", "É, então por favor não conte a ela."]], ["O som /p/ em party e Peg", "Feche os lábios e solte um sopro forte. Ponha a mão na frente da boca: você sente o ar.", ["party", "Peg has a party."]], ["Ben calls the guests ___ they come at five.", "so", "because", "O Ben liga para os convidados, então eles vêm às cinco.", "So mostra o resultado; porque o Ben liga, eles vêm."]];
patterns[289]=new RegExp("\\b(party|guests?)\\b","i");
themes[289]="cup";
photos[289]=["photo-dinner-2.webp", "photo-friends-1.webp"];
stories[289]=["A festa surpresa da Peg", "Ben wants to give Peg a big party.~O Ben quer dar uma grande festa para a Peg.|He sends an invitation to every friend.~Ele envia um convite a cada amigo.|Ava says, “Thank you for the invitation.”~A Ava diz: “Obrigada pelo convite.”|Her birthday is on April twentieth.~O aniversário dela é no dia vinte de abril.|Ravi buys a cake because Peg loves cake.~O Ravi compra um bolo porque a Peg adora bolo.|But the cake is too big for his bag.~Mas o bolo é grande demais para a mochila dele.|Ben calls him and says, “Wait for me.”~O Ben liga para ele e diz: “Espere por mim.”|Together they carry it to the house.~Juntos eles levam o bolo até a casa.|Peg comes in, and the guests sing.~A Peg entra, e os convidados cantam.|She hugs them and says, “Thank you!”~Ela abraça todos e diz: “Obrigada!”"];
extras[289]={"clap": ["We clap for you.", "Nós batemos palmas para você."], "balloon": ["I have a blue balloon.", "Eu tenho um balão azul."]};
plans[290]={"title": "Quem é o Lou?", "file": "photo-friends-1.webp", "grammar": "Descrever pessoas: tall, short, young, old e has + cor de cabelo", "goal": "Use be + tall, short, young, old e has + cor de cabelo para descrever uma pessoa.", "words": [["tall", "alto"], ["glasses", "óculos"], ["hair", "cabelo"], ["young", "jovem"]]};
content[290]=[[["Ava waits for Lou at the square.", "A Ava espera o Lou na praça."], ["Lou is tall and young, about twenty.", "O Lou é alto e jovem, tem uns vinte anos."], ["He has short brown hair and glasses.", "Ele tem cabelo castanho curto e óculos."], ["His grandfather is old, but he is tall too.", "O avô dele é velho, mas também é alto."], ["Ava sees him and waves.", "A Ava o vê e acena."]], [["Is Lou the tall boy?", "O Lou é o garoto alto?"], ["Yes, he is. He has glasses.", "É, sim. Ele usa óculos."], ["What color is his hair?", "Qual é a cor do cabelo dele?"], ["He has short brown hair.", "Ele tem cabelo castanho curto."], ["Is he young or old?", "Ele é jovem ou velho?"], ["He is young. He is twenty.", "Ele é jovem. Tem vinte anos."], ["Do you see him near the bench?", "Você o vê perto do banco?"], ["Yes, he is the tall one there.", "Vejo. Ele é o alto ali."]], ["O som /t/ em tall", "Toque a ponta da língua atrás dos dentes de cima e solte com um sopro. O ll final é um l escuro.", ["tall", "Lou is tall."]], ["Lou ___ brown hair.", "has", "is", "O Lou tem cabelo castanho.", "Para cabelo, use has: he has brown hair. Is é para tall, young e old."]];
patterns[290]=new RegExp("\\b(is|has) (tall|young|old|short|brown|black)","i");
