content[294]=[[["Lou lives on a small street.", "O Lou mora em uma rua pequena."], ["There is a bank on the corner.", "Há um banco na esquina."], ["There is a bus stop next to it.", "Há um ponto de ônibus ao lado dele."], ["There are two shops and a school.", "Há duas lojas e uma escola."], ["There are no cars on Sunday.", "Não há carros no domingo."]], [["What is on your street, Lou?", "O que tem na sua rua, Lou?"], ["There is a bank on the corner.", "Tem um banco na esquina."], ["Is there a bus stop?", "Tem um ponto de ônibus?"], ["Yes, there is. It is near the bank.", "Tem, sim. Fica perto do banco."], ["Are there any shops?", "Tem alguma loja?"], ["Yes, there are three shops.", "Tem, sim. Há três lojas."], ["Is there a park too?", "Tem um parque também?"], ["No, but there are trees.", "Não, mas há árvores."]], ["O som /ɔr/ em corner", "A boca fica arredondada: COR-ner. O r do meio é inglês, com a língua puxada para trás.", ["corner", "The bank is on the corner."]], ["___ two shops on my street.", "There are", "There is", "Há duas lojas na minha rua.", "Com plural (two shops), use There are."]];
