content[295]=[[["Tina likes the mall, but it is noisy.", "A Tina gosta da shopping, mas ela é barulhenta."], ["The hill is quiet and very clean.", "O colina é quieto e muito limpo."], ["She can stay here or walk to the hill.", "Ela pode ficar aqui ou caminhar até o colina."], ["She wants quiet, so she goes to the hill.", "Ela quer sossego, então vai ao colina."], ["She sits down and reads a book.", "Ela se senta e lê um livro."]], [["Is the mall quiet or noisy?", "A shopping é quieta ou barulhenta?"], ["It is noisy, but it is fun.", "É barulhenta, mas é divertida."], ["Is the hill clean?", "O colina é limpo?"], ["Yes, it is clean and quiet.", "É, sim. É limpo e quieto."], ["Do you want to sit here or there?", "Você quer sentar aqui ou lá?"], ["Let us sit on the hill.", "Vamos sentar no colina."], ["Why there?", "Por que lá?"], ["I want quiet, so I like the hill.", "Quero sossego, então gosto do colina."]], ["O som /ɔɪ/ em noisy", "Comece com a boca arredondada e termine num i: NOI-zy. O s no meio soa como z.", ["noisy", "The street is noisy."]], ["It is noisy, ___ it is fun.", "but", "and", "É barulhento, mas é divertido.", "But liga duas ideias que contrastam; and apenas soma."]];
